     8	
     9	const redisUrl = process.env.REDIS_URL || 'redis://host.docker.internal:6379';
    10	console.log('[queue] Using Redis URL:', redisUrl);
    11	const connection = new IORedis(redisUrl, {
    12	  maxRetriesPerRequest: null,
    13	  tls: process.env.REDIS_URL?.startsWith('rediss://') ? {} : undefined,
    14	});
    15	
    16	export const rawEventsQueue = new Queue<RawEventInput>('raw_events', {
    17	  connection,
    18	  defaultJobOptions: {
    19	    attempts: 3,
    20	    backoff: { type: 'exponential', delay: 5000 },
    21	    removeOnComplete: 100,
    22	    removeOnFail: 500,
    23	  },
    24	});
    25	
    26	export const searchSyncQueue = new Queue<{ event_id: string; action: 'upsert' | 'delete' }>(
    27	  'search_sync',
    28	  { connection }
    29	);
    30	
    31	export function createNormalizerWorker(
    32	  processor: (job: Job<RawEventInput>) => Promise<void>
    33	) {
    34	  const worker = new Worker<RawEventInput>('raw_events', processor, {
    35	    connection,
    36	    concurrency: 5,
    37	  });
    38	
    39	  return worker;
    40	}
